// 本文件定义 Bubble Tea TUI 对外暴露的 UI 适配器。
package bubble

import (
	"codex-agent-go/internal/message"
	"codex-agent-go/internal/model"
	"codex-agent-go/internal/session"
	"codex-agent-go/internal/settings"
	"codex-agent-go/internal/subagent"
	"codex-agent-go/internal/ui"
	"context"
	"errors"
	"fmt"
	tea "github.com/charmbracelet/bubbletea"
	"os"
	"sync"
)

// Runner 描述 TUI 提交一轮用户输入时需要调用的对话运行器。
type Runner interface {
	RunTurn(ctx context.Context, input string) (message.Message, error)
	ResetHistory()
	LoadHistory(ctx context.Context, sessionID string) ([]message.Message, error)
}

// SupplementSubmitter describes runners that can accept instructions while a
// model turn is already running.
type SupplementSubmitter interface {
	SubmitSupplement(input string) bool
}

// SupplementStatsProvider exposes pending supplement counts for status UI.
type SupplementStatsProvider interface {
	PendingSupplementCount() int
}

// SessionStore 描述 TUI 列举和管理会话所需的最小接口。
type SessionStore interface {
	ListSessions(ctx context.Context) ([]session.SessionSummary, error)
}

// ModelConfigController 描述运行时读取和应用模型配置的控制器。
type ModelConfigController interface {
	CurrentModelConfig() model.Config
	ApplyModelConfig(model.Config) error
}

// ModelConfigSaver 描述可将模型配置持久化到磁盘的控制器扩展。
type ModelConfigSaver interface {
	SaveModelConfig(model.Config) error
}

// SettingsController 描述运行时读取和保存 UI/agent 设置的控制器。
type SettingsController interface {
	CurrentSettings() settings.Config
	SaveSettings(settings.Config) error
}

// SubagentController 描述 TUI 手动启动和查看 subagent 所需的能力。
type SubagentController interface {
	Run(context.Context, subagent.Request) (subagent.Result, error)
	Launch(context.Context, subagent.Request) (subagent.TaskSnapshot, error)
	ListTasks() []subagent.TaskSnapshot
}

// UI 是基于 Bubble Tea 的交互式终端界面实现。
type UI struct {
	mu                    sync.Mutex
	program               *tea.Program
	modelConfigController ModelConfigController
	settingsController    SettingsController
	subagentController    SubagentController
	sessionStore          SessionStore
}

// 确保 UI 满足通用终端 UI 接口。
var _ ui.UI = (*UI)(nil)

// New 创建一个尚未启动的 Bubble Tea UI 实例。
func New() *UI {
	return &UI{}
}

// SetModelConfigController 注入模型配置控制器，供 /model 向导读取和保存配置。
func (u *UI) SetModelConfigController(controller ModelConfigController) {
	u.mu.Lock()
	defer u.mu.Unlock()
	u.modelConfigController = controller
}

// SetSettingsController 注入 settings 控制器，供 /setting 和状态栏读取。
func (u *UI) SetSettingsController(controller SettingsController) {
	u.mu.Lock()
	defer u.mu.Unlock()
	u.settingsController = controller
}

// SetSubagentController 注入 subagent 控制器，供 /subagent 和 /tasks 使用。
func (u *UI) SetSubagentController(controller SubagentController) {
	u.mu.Lock()
	defer u.mu.Unlock()
	u.subagentController = controller
}

// SetSessionStore 注入 session store，供 /sessions 命令列举历史会话。
func (u *UI) SetSessionStore(store SessionStore) {
	u.mu.Lock()
	defer u.mu.Unlock()
	u.sessionStore = store
}

// Run 启动 Bubble Tea 主循环，并把输出写入带光标锚点修正的终端流。
func (u *UI) Run(ctx context.Context, runner Runner, sessionID string) error {
	u.mu.Lock()
	controller := u.modelConfigController
	settingsController := u.settingsController
	subagentController := u.subagentController
	sessionStore := u.sessionStore
	u.mu.Unlock()

	anchor := newTerminalCursorAnchor()
	appModel := newModel(ctx, runner, sessionID, controller, settingsController, subagentController, sessionStore, anchor)
	// WithInput 包一层 ESC 聚合 reader：在 BubbleTea 解析字节之前，把被读边界
	// 切断的 \x1b[<...M 鼠标序列重新拼合，从源头杜绝 ESC 与 [ 分离导致的
	// [[[[[[[ 泄漏。reader 内嵌 *os.File，MakeRaw 与 kqueue 路径不受影响。
	program := tea.NewProgram(
		appModel,
		tea.WithContext(ctx),
		tea.WithInput(newESCCoalescingReader(os.Stdin)),
		tea.WithOutput(newAnchoredOutput(os.Stdout, anchor)),
		tea.WithAltScreen(),
		tea.WithMouseCellMotion(),
	)

	u.mu.Lock()
	u.program = program
	u.mu.Unlock()

	_, err := program.Run()

	u.mu.Lock()
	if u.program == program {
		u.program = nil
	}
	u.mu.Unlock()

	if errors.Is(err, tea.ErrInterrupted) {
		return nil
	}
	return err
}

// OnAssistantDelta 接收模型流式文本增量，并转发给 Bubble Tea 状态机。
func (u *UI) OnAssistantDelta(text string) error {
	if text == "" {
		return nil
	}
	return u.send(assistantDeltaMsg(text))
}

// OnThinkingDelta 接收模型 thinking 流，并转发给 Bubble Tea 状态机。
func (u *UI) OnThinkingDelta(text string) error {
	if text == "" {
		return nil
	}
	return u.send(thinkingDeltaMsg(text))
}

// OnToolCall 接收工具调用事件，并转发给 Bubble Tea 状态机展示。
func (u *UI) OnToolCall(event ui.ToolCallEvent) error {
	return u.send(toolCallMsg(event))
}

// OnToolResult 接收工具结果事件，并转发给 Bubble Tea 状态机展示。
func (u *UI) OnToolResult(event ui.ToolResultEvent) error {
	return u.send(toolResultMsg(event))
}

// OnDone 通知 TUI 当前 assistant 响应已经结束。
func (u *UI) OnDone() error {
	return u.send(doneMsg{})
}

// ConsumesOldContent 声明 bubble UI 会消费 OldContent 用于 diff 展示。
func (u *UI) ConsumesOldContent() bool { return true }

// OnSystemMessage 接收后台任务等系统事件，并转发给 Bubble Tea 状态机展示。
func (u *UI) OnSystemMessage(event ui.SystemEvent) error {
	return u.send(systemEventMsg(event))
}

// send 将外部事件安全地投递到正在运行的 Bubble Tea program。
func (u *UI) send(msg tea.Msg) error {
	u.mu.Lock()
	program := u.program
	u.mu.Unlock()
	if program == nil {
		return fmt.Errorf("bubble UI program is not running")
	}
	program.Send(msg)
	return nil
}

// 本文件定义 Bubble Tea 主界面的固定外框、底部 dock 和终端光标锚点计算。
package bubble

import (
	"strings"

	"github.com/charmbracelet/bubbles/textarea"
	"github.com/charmbracelet/lipgloss"
)

const (
	mainFrameHorizontalFrame = 2
	mainFrameVerticalFrame   = 2
	mainContentPadding       = 1
	dockStatusHeight         = 1
)

// tuiLayout 是由终端尺寸和输入高度唯一决定的纯布局结果。
// frame 的尺寸只随 WindowSizeMsg 改变，内容更新只能改变内部区域。
type tuiLayout struct {
	frameWidth       int
	frameHeight      int
	contentWidth     int
	contentHeight    int
	headerHeight     int
	transcriptHeight int
	statusHeight     int
	inputHeight      int
}

func computeTUILayout(width, height, requestedInputHeight int) tuiLayout {
	frameWidth := maxInt(1, width)
	frameHeight := maxInt(1, height)
	contentWidth := maxInt(1, frameWidth-mainFrameHorizontalFrame)
	contentHeight := maxInt(1, frameHeight-mainFrameVerticalFrame)

	// header 在内容足够高时占 1 行；极小终端优先保留 transcript+input。
	headerHeight := 0
	if contentHeight >= 4 {
		headerHeight = dockStatusHeight
	}
	statusHeight := 0
	if contentHeight-headerHeight >= 2 {
		statusHeight = dockStatusHeight
	}

	inputHeight := clampInt(requestedInputHeight, 1, inputMaxVisibleLines)
	// 正常尺寸下始终给 transcript 留至少一行；极小终端优先保留输入。
	maxInputHeight := maxInt(1, contentHeight-headerHeight-statusHeight-1)
	inputHeight = minInt(inputHeight, maxInputHeight)
	if inputHeight+headerHeight+statusHeight > contentHeight {
		inputHeight = maxInt(1, contentHeight-headerHeight-statusHeight)
	}
	transcriptHeight := maxInt(0, contentHeight-headerHeight-statusHeight-inputHeight)

	return tuiLayout{
		frameWidth:       frameWidth,
		frameHeight:      frameHeight,
		contentWidth:     contentWidth,
		contentHeight:    contentHeight,
		headerHeight:     headerHeight,
		transcriptHeight: transcriptHeight,
		statusHeight:     statusHeight,
		inputHeight:      inputHeight,
	}
}

func (m appModel) currentLayout() tuiLayout {
	inputHeight := m.input.Height()
	if inputHeight <= 0 {
		inputHeight = inputMinVisibleLines
	}
	return computeTUILayout(m.width, m.height, inputHeight)
}

// View 渲染一个尺寸严格等于当前终端的单一固定外框。
func (m appModel) View() string {
	if !m.ready {
		if m.cursorAnchor != nil {
			m.cursorAnchor.clear()
		}
		return "Starting Bubble Tea..."
	}

	layout := m.currentLayout()
	parts := make([]string, 0, 4)
	if layout.headerHeight > 0 {
		parts = append(parts, m.renderHeaderLine(layout.contentWidth))
	}
	if layout.transcriptHeight > 0 {
		parts = append(parts, m.renderTranscriptRegion(layout))
	}
	if layout.statusHeight > 0 {
		parts = append(parts, m.renderDockStatusLine(layout.contentWidth))
	}
	parts = append(parts, m.renderInputBoxForLayout(layout))

	inner := fitStyledRect(strings.Join(parts, "\n"), layout.contentWidth, layout.contentHeight)
	view := renderFixedStyledPanel(mainFrameStyle, layout.frameWidth, layout.frameHeight, inner)
	m.updateTerminalCursorAnchor(layout)
	return fitStyledRect(view, layout.frameWidth, layout.frameHeight)
}

func (m appModel) renderTranscriptRegion(layout tuiLayout) string {
	if layout.transcriptHeight <= 0 {
		return ""
	}

	base := renderFixedStyledPanel(
		transcriptContentStyle,
		layout.contentWidth,
		layout.transcriptHeight,
		m.viewport.View(),
	)

	if modal := m.renderActiveModalBox(layout); modal != "" {
		return placeOpaqueOverlay(
			base,
			modal,
			layout.contentWidth,
			layout.transcriptHeight,
			overlayAlignCenter,
		)
	}

	if m.completion != nil {
		return placeOpaqueOverlay(
			base,
			m.renderCompletionBox(),
			layout.contentWidth,
			layout.transcriptHeight,
			overlayAlignBottom,
		)
	}
	return fitStyledRect(base, layout.contentWidth, layout.transcriptHeight)
}

func (m appModel) renderActiveModalBox(layout tuiLayout) string {
	if layout.transcriptHeight <= 0 {
		return ""
	}
	switch {
	case m.modelWizard != nil:
		return m.renderModelWizardBox()
	case m.settingWizard != nil:
		return m.renderSettingWizardBox()
	case m.sessionPicker != nil:
		return m.renderSessionPickerBox()
	case m.subagentPicker != nil:
		return m.renderActivityBox()
	default:
		return ""
	}
}

type overlayAlignment int

const (
	overlayAlignCenter overlayAlignment = iota
	overlayAlignBottom
)

func placeOpaqueOverlay(base, overlay string, width, height int, alignment overlayAlignment) string {
	base = fitStyledRect(base, width, height)
	overlayWidth := minInt(width, maxInt(1, widestStyledLine(overlay)))
	overlayHeight := minInt(height, maxInt(1, lipgloss.Height(overlay)))
	overlay = fitStyledRect(overlay, overlayWidth, overlayHeight)

	left := maxInt(0, (width-overlayWidth)/2)
	top := maxInt(0, (height-overlayHeight)/2)
	if alignment == overlayAlignBottom {
		top = maxInt(0, height-overlayHeight)
	}

	baseLines := strings.Split(base, "\n")
	overlayLines := strings.Split(overlay, "\n")
	for row, overlayLine := range overlayLines {
		baseRow := top + row
		if baseRow < 0 || baseRow >= len(baseLines) {
			continue
		}
		baseLines[baseRow] = composeStyledCellOverlay(baseLines[baseRow], overlayLine, left, width)
	}
	return strings.Join(baseLines, "\n")
}

func widestStyledLine(text string) int {
	width := 0
	for _, line := range strings.Split(text, "\n") {
		width = maxInt(width, terminalCellWidth(line))
	}
	return width
}

// renderModalPanel 将 modal 限制在 transcript 区域内，内容过长时进行显示层裁剪。
func (m appModel) renderModalPanel(body string) string {
	layout := m.currentLayout()
	availableWidth := maxInt(1, layout.contentWidth-4)
	availableHeight := maxInt(1, layout.transcriptHeight-2)
	panelWidth := minInt(80, availableWidth)
	if availableWidth >= 32 {
		panelWidth = maxInt(32, panelWidth)
	}
	naturalHeight := lipgloss.Height(body) + modalPanelVerticalFrame
	panelHeight := minInt(availableHeight, maxInt(modalPanelVerticalFrame+1, naturalHeight))
	return renderFixedStyledPanel(wizardPanelStyle, panelWidth, panelHeight, body)
}

func (m appModel) renderCompletionPanel(body string) string {
	layout := m.currentLayout()
	panelWidth := minInt(72, maxInt(1, layout.contentWidth))
	panelHeight := minInt(
		maxInt(1, layout.transcriptHeight),
		maxInt(completionPanelVerticalFrame+1, lipgloss.Height(body)+completionPanelVerticalFrame),
	)
	return renderFixedStyledPanel(completionPanelStyle, panelWidth, panelHeight, body)
}

func renderFixedStyledPanel(style lipgloss.Style, totalWidth, totalHeight int, body string) string {
	totalWidth = maxInt(1, totalWidth)
	totalHeight = maxInt(1, totalHeight)
	horizontalBorder := style.GetHorizontalBorderSize()
	verticalBorder := style.GetVerticalBorderSize()
	horizontalPadding := style.GetHorizontalPadding()
	verticalPadding := style.GetVerticalPadding()
	// Lipgloss Width/Height include padding but are applied before borders.
	// The body must therefore fit inside the width/height left after padding,
	// while the style dimensions only subtract the border itself.
	styleWidth := maxInt(1, totalWidth-horizontalBorder)
	styleHeight := maxInt(1, totalHeight-verticalBorder)
	bodyWidth := maxInt(1, styleWidth-horizontalPadding)
	bodyHeight := maxInt(1, styleHeight-verticalPadding)
	body = fitStyledRect(body, bodyWidth, bodyHeight)
	rendered := style.
		Width(styleWidth).
		Height(styleHeight).
		Render(body)
	return fitStyledRect(rendered, totalWidth, totalHeight)
}

// fitStyledRect 对带 ANSI 样式的矩形按终端 cell 宽度裁剪并补齐。
func fitStyledRect(text string, width, height int) string {
	if width <= 0 || height <= 0 {
		return ""
	}
	lines := strings.Split(strings.TrimSuffix(text, "\n"), "\n")
	if len(lines) > height {
		lines = lines[:height]
	}
	for len(lines) < height {
		lines = append(lines, "")
	}
	for i, line := range lines {
		lines[i] = fitStyledCellLine(line, width)
	}
	return strings.Join(lines, "\n")
}

// renderActiveInputPanel 保留为输入区兼容入口；modal 和 completion 已移入 transcript 浮层。
func (m appModel) renderActiveInputPanel() string {
	return m.renderInputBox()
}

// updateTerminalCursorAnchor 根据固定 input 矩形更新终端真实光标锚点。
func (m appModel) updateTerminalCursorAnchor(layout tuiLayout) {
	if m.cursorAnchor == nil {
		return
	}
	if !m.shouldAnchorTextInputCursor() {
		m.cursorAnchor.clear()
		return
	}
	m.cursorAnchor.set(m.inputCursorTerminalPosition(layout))
}

func (m appModel) shouldAnchorTextInputCursor() bool {
	return m.ready &&
		!m.isTerminalWorkRunning() &&
		!m.toolInspectActive &&
		m.modelWizard == nil &&
		m.settingWizard == nil &&
		m.sessionPicker == nil &&
		m.subagentPicker == nil
}

// inputCursorTerminalPosition 直接由固定布局矩形计算，不再依赖拼接后字符串高度。
func (m appModel) inputCursorTerminalPosition(layout tuiLayout) terminalCursorPosition {
	row := minInt(m.visibleInputCursorRow(), maxInt(0, layout.inputHeight-1))
	upFromBottom := 1 + maxInt(0, layout.inputHeight-row-1)
	column := 2 + m.visibleInputCursorColumn()
	column = minInt(column, maxInt(0, layout.frameWidth-1))
	return terminalCursorPosition{
		active:       true,
		upFromBottom: upFromBottom,
		column:       maxInt(0, column),
	}
}

func (m appModel) inputEmbeddedTitleHeight() int {
	return 0
}

func (m appModel) visibleInputCursorRow() int {
	if len(m.inputTokens) > 0 {
		projection := m.inputTokenProjection()
		height := maxInt(1, m.input.Height())
		start := 0
		if len(projection.lines) > height && projection.cursorRow >= height {
			start = projection.cursorRow - height + 1
		}
		start = clampInt(start, 0, maxInt(0, len(projection.lines)-height))
		return clampInt(projection.cursorRow-start, 0, height-1)
	}
	if m.shouldRenderFoldedInput() {
		return foldedInputCursorRow(m.input)
	}
	return visibleTextareaCursorRow(m.input)
}

func (m appModel) visibleInputCursorColumn() int {
	if len(m.inputTokens) > 0 {
		return maxInt(0, m.inputTokenProjection().cursorColumn)
	}
	if m.shouldRenderFoldedInput() {
		return minInt(maxInt(0, m.input.LineInfo().CharOffset), maxInt(0, m.input.Width()-1))
	}
	return visibleTextareaCursorColumn(m.input)
}

func visibleTextareaCursorRow(input textarea.Model) int {
	lineInfo := input.LineInfo()
	row := input.Line() + lineInfo.RowOffset
	return minInt(maxInt(0, row), maxInt(0, input.Height()-1))
}

func visibleTextareaCursorColumn(input textarea.Model) int {
	return maxInt(0, input.LineInfo().CharOffset)
}

// renderInputBox 渲染普通输入、多行输入、终端输入和等待状态的 dock 输入区。
func (m appModel) renderInputBox() string {
	return m.renderInputBoxForLayout(m.currentLayout())
}

func (m appModel) renderInputBoxForLayout(layout tuiLayout) string {
	style := inputDockStyle
	if m.isTerminalInputActive() || m.runningTerminal {
		style = inputDockTerminalStyle
	} else if m.hasMultilineInput() {
		style = inputDockMultilineStyle
	}
	return renderFixedStyledPanel(style, layout.contentWidth, layout.inputHeight, m.renderInputContent())
}

func (m appModel) renderInputContent() string {
	if len(m.inputTokens) > 0 {
		return m.renderTokenInputContent()
	}
	input := m.input
	if m.isTerminalInputActive() || m.runningTerminal {
		applyTextareaTerminalStyle(&input)
	}
	if m.shouldRenderFoldedInput() {
		return renderFoldedInputContent(input)
	}
	return input.View()
}

// applyTextareaTerminalStyle 显式覆盖 textarea 自己的子样式，避免灰色 Placeholder
// 遮蔽 terminal Dock 的父级前景色。
func applyTextareaTerminalStyle(input *textarea.Model) {
	if input == nil {
		return
	}
	input.Placeholder = "$"
	input.FocusedStyle.Text = terminalInputTextStyle
	input.BlurredStyle.Text = terminalInputTextStyle
	input.FocusedStyle.Placeholder = terminalInputLabelStyle
	input.BlurredStyle.Placeholder = terminalInputLabelStyle
}

func (m appModel) shouldRenderFoldedInput() bool {
	return m.inputPasteFoldActive &&
		inputPasteFoldable(m.input.Value()) &&
		!inputCursorInPasteFoldHiddenRange(m.input)
}

func renderFoldedInputContent(input textarea.Model) string {
	projected, _, ok := inputPasteFoldProjection(input.Value())
	if !ok {
		return input.View()
	}
	width := maxInt(1, input.Width())
	height := maxInt(1, input.Height())
	lines := make([]string, 0, height)
	for _, line := range projected {
		if len(lines) >= height {
			break
		}
		lines = append(lines, padDisplayWidth(truncateDisplayWidth(line, width), width))
	}
	for len(lines) < height {
		lines = append(lines, strings.Repeat(" ", width))
	}
	return strings.Join(lines, "\n")
}

func foldedInputCursorRow(input textarea.Model) int {
	start, end, ok := inputPasteFoldHiddenRange(input.Value())
	if !ok {
		return visibleTextareaCursorRow(input)
	}
	line := input.Line()
	if line < start {
		return minInt(maxInt(0, line), maxInt(0, input.Height()-1))
	}
	row := start + 1 + (line - end)
	return minInt(maxInt(0, row), maxInt(0, input.Height()-1))
}

// renderTranscriptBox 保留给测试和旧调用点，实际 transcript 不再拥有独立外框。
func (m appModel) renderTranscriptBox() string {
	return m.renderTranscriptRegion(m.currentLayout())
}

func (m appModel) leftPanelContentWidth(minWidth int) int {
	return maxInt(minWidth, m.viewport.Width)
}

func (m appModel) renderHeader() string { return "" }
func (m appModel) headerHeight() int    { return 0 }
func (m appModel) headerText() string   { return "" }

// relayout 只根据终端尺寸和输入视觉行数计算内部区域。
func (m *appModel) relayout() {
	if m.width <= 0 || m.height <= 0 {
		// Bubble Tea 尚未发送首个 WindowSizeMsg 时保留 textarea/viewport 的
		// 初始化尺寸，避免输入事件把宽度暂时压成 1。
		m.input.SetHeight(m.tokenAwareInputVisibleLineCount())
		return
	}
	base := computeTUILayout(m.width, m.height, inputMinVisibleLines)
	inputWidth := maxInt(1, base.contentWidth-mainContentPadding*2)
	m.input.SetWidth(inputWidth)

	requestedInputHeight := m.tokenAwareInputVisibleLineCount()
	layout := computeTUILayout(m.width, m.height, requestedInputHeight)
	m.input.SetHeight(layout.inputHeight)
	m.viewport.Width = inputWidth
	m.viewport.Height = maxInt(1, layout.transcriptHeight)
}

func (m appModel) tokenAwareInputVisibleLineCount() int {
	if len(m.inputTokens) == 0 {
		return inputVisibleLineCount(m.input)
	}
	projection := m.inputTokenProjection()
	return minInt(inputMaxVisibleLines, maxInt(inputMinVisibleLines, len(projection.lines)))
}

// expandTranscriptToFillHeight 已由纯布局计算器取代，保留空实现供旧调用点平滑迁移。
func (m *appModel) expandTranscriptToFillHeight() {}

// 本文件定义聊天历史 transcript 的追加、刷新和逐条渲染逻辑。
package bubble

import (
	"encoding/json"
	"strconv"
	"strings"
	"time"

	"github.com/charmbracelet/lipgloss"
	"github.com/charmbracelet/x/ansi"
)

const transcriptStreamingRefreshInterval = cursorFrameInterval
const maxRenderedToolDetailLines = 12
const transcriptEntryGutter = "  "

type transcriptRenderCacheEntry struct {
	key      transcriptRenderCacheKey
	rendered string
}

type transcriptRenderCacheKey struct {
	kind            entryKind
	renderMode      transcriptRenderMode
	title           string
	body            string
	inputTokens     string
	color           string
	isError         bool
	toolUseID       string
	toolName        string
	toolStatus      string
	toolTarget      string
	toolResult      string
	toolResultLen   int
	toolExpanded    bool
	toolFocused     bool
	toolHovered     bool
	toolResultOnly  bool
	citations       string
	width           int
	version         int
	bodyLen         int
	citationCount   int
	createdAtUnixNS int64
	createdAtIsZero bool
}

func (m *appModel) ensureAssistantStreamEntry() {
	if m.activeAssistant < 0 || m.activeAssistant >= len(m.transcript) || m.transcript[m.activeAssistant].kind != entryAssistant {
		m.transcript = append(m.transcript, transcriptEntry{
			kind:       entryAssistant,
			title:      "assistant",
			citations:  m.consumePendingToolCitations(),
			createdAt:  m.animationNow(),
			renderMode: transcriptRenderFormatted,
		})
		m.activeAssistant = len(m.transcript) - 1
	} else if len(m.pendingToolCites) > 0 {
		m.transcript[m.activeAssistant].citations = append(m.transcript[m.activeAssistant].citations, m.consumePendingToolCitations()...)
	}
	if m.transcript[m.activeAssistant].renderMode != transcriptRenderFormatted {
		m.transcript[m.activeAssistant].renderMode = transcriptRenderFormatted
		touchTranscriptEntry(&m.transcript[m.activeAssistant])
	}
}

// appendAssistantDelta 将经过流隔离器确认的稳定文本逐行追加到当前 assistant 消息。
func (m *appModel) appendAssistantDelta(delta string) {
	if delta == "" {
		return
	}
	for _, line := range strings.SplitAfter(delta, "\n") {
		m.ensureAssistantStreamEntry()
		m.transcript[m.activeAssistant].body += line
		touchTranscriptEntry(&m.transcript[m.activeAssistant])
		m.refreshViewport()
	}
}

func (m *appModel) ensureThinkingStreamEntry() {
	m.activeAssistant = -1
	if m.activeThinking < 0 || m.activeThinking >= len(m.transcript) || m.transcript[m.activeThinking].kind != entryThinking {
		m.transcript = append(m.transcript, transcriptEntry{
			kind:       entryThinking,
			title:      "thinking",
			createdAt:  m.animationNow(),
			renderMode: transcriptRenderPlain,
		})
		m.activeThinking = len(m.transcript) - 1
	}
}

// appendThinkingDelta 将经过流隔离器确认的稳定 thinking 文本追加到 transcript。
func (m *appModel) appendThinkingDelta(delta string) {
	if delta == "" {
		return
	}
	m.ensureThinkingStreamEntry()
	m.transcript[m.activeThinking].body += delta
	touchTranscriptEntry(&m.transcript[m.activeThinking])
	m.refreshViewportForStreaming()
}

func (m *appModel) consumeAssistantStreamDelta(delta string) {
	if delta == "" {
		return
	}
	if m.thinkingStream.HasContent() {
		m.finalizeThinkingStream()
	}
	committed := m.assistantStream.Push(delta, m.streamingBodyWidth())
	if m.assistantStream.HasContent() {
		m.ensureAssistantStreamEntry()
	}
	m.appendAssistantDelta(committed)
}

func (m *appModel) consumeThinkingStreamDelta(delta string) {
	if delta == "" {
		return
	}
	if m.assistantStream.HasContent() {
		m.finalizeAssistantStream(transcriptRenderFormatted)
	}
	committed := m.thinkingStream.Push(delta, m.streamingBodyWidth())
	if m.thinkingStream.HasContent() {
		m.ensureThinkingStreamEntry()
	}
	m.appendThinkingDelta(committed)
}

func (m *appModel) finalizeAssistantStream(mode transcriptRenderMode) int {
	hadContent := m.assistantStream.HasContent()
	committed := m.assistantStream.Flush(m.streamingBodyWidth())
	if hadContent {
		m.ensureAssistantStreamEntry()
	}
	m.appendAssistantDelta(committed)
	finalized := m.activeAssistant
	m.setAssistantRenderMode(finalized, mode)
	m.activeAssistant = -1
	return finalized
}

func (m *appModel) setAssistantRenderMode(index int, mode transcriptRenderMode) {
	if index < 0 || index >= len(m.transcript) || m.transcript[index].kind != entryAssistant {
		return
	}
	if m.transcript[index].renderMode != mode {
		m.transcript[index].renderMode = mode
		touchTranscriptEntry(&m.transcript[index])
		m.refreshViewport()
	}
}

func (m *appModel) finalizeThinkingStream() {
	hadContent := m.thinkingStream.HasContent()
	committed := m.thinkingStream.Flush(m.streamingBodyWidth())
	if hadContent {
		m.ensureThinkingStreamEntry()
	}
	m.appendThinkingDelta(committed)
	m.activeThinking = -1
}

func (m *appModel) resizeStreamingBuffers() {
	width := m.streamingBodyWidth()
	if committed := m.assistantStream.Resize(width); committed != "" {
		m.ensureAssistantStreamEntry()
		m.appendAssistantDelta(committed)
	}
	if committed := m.thinkingStream.Resize(width); committed != "" {
		m.ensureThinkingStreamEntry()
		m.appendThinkingDelta(committed)
	}
}

func (m *appModel) resetStreamingBuffers() {
	m.assistantStream.Reset()
	m.thinkingStream.Reset()
	m.activeAssistant = -1
	m.activeThinking = -1
	m.doneAssistant = -1
}

func (m appModel) streamingBodyWidth() int {
	return transcriptBodyWidth(maxInt(20, m.viewport.Width))
}

// addEntry 追加一条 transcript 记录并刷新滚动区。
func (m *appModel) addEntry(entry transcriptEntry) {
	if entry.createdAt.IsZero() {
		entry.createdAt = m.animationNow()
	}
	touchTranscriptEntry(&entry)
	m.transcript = append(m.transcript, entry)
	m.refreshViewport()
}

func (m appModel) animationNow() time.Time {
	if !m.cursorFrameAt.IsZero() {
		return m.cursorFrameAt
	}
	return time.Now()
}

func touchTranscriptEntry(entry *transcriptEntry) {
	if entry == nil {
		return
	}
	entry.version++
	if entry.version <= 0 {
		entry.version = 1
	}
}

func (m *appModel) consumePendingToolCitations() []toolCitation {
	if len(m.pendingToolCites) == 0 {
		return nil
	}
	cites := append([]toolCitation(nil), m.pendingToolCites...)
	m.pendingToolCites = nil
	return cites
}

func (m *appModel) recordToolCallCitation(toolUseID, name string, input json.RawMessage) {
	cite := newToolCallCitation(toolUseID, name, input)
	if idx := m.lastAssistantCitationHostIndex(); idx >= 0 {
		m.transcript[idx].citations = append(m.transcript[idx].citations, cite)
		touchTranscriptEntry(&m.transcript[idx])
	} else {
		entry := transcriptEntry{
			kind:      entryAssistant,
			title:     "assistant",
			citations: []toolCitation{cite},
			createdAt: m.animationNow(),
		}
		touchTranscriptEntry(&entry)
		m.transcript = append(m.transcript, entry)
	}
	m.refreshViewport()
}

func (m *appModel) recordToolCallEntry(toolUseID, name string, input json.RawMessage, oldContent string) {
	name = strings.TrimSpace(name)
	if name == "" {
		name = "tool"
	}
	m.addEntry(transcriptEntry{
		kind:       entryTool,
		title:      "tool",
		body:       formatRunningToolCallBody(name, input, oldContent),
		toolUseID:  strings.TrimSpace(toolUseID),
		toolName:   name,
		toolStatus: "running",
		toolTarget: toolSummaryTarget(name, input),
		createdAt:  m.animationNow(),
	})
}

func (m *appModel) recordToolResultEntry(toolUseID, name, status, content string, isError bool) {
	name = strings.TrimSpace(name)
	if name == "" {
		name = "tool"
	}
	status = strings.TrimSpace(status)
	if status == "" {
		status = "ok"
	}
	result := toolEntryResult{
		toolUseID: strings.TrimSpace(toolUseID),
		name:      name,
		status:    status,
		isError:   isError,
	}
	for idx := len(m.transcript) - 1; idx >= 0; idx-- {
		entry := &m.transcript[idx]
		if !toolEntryMatchesResult(*entry, result) {
			continue
		}
		entry.title = "tool"
		entry.body = completeRunningToolCallBody(entry.body, status)
		entry.isError = isError
		entry.toolStatus = status
		entry.toolResult = content
		entry.toolExpanded = isError
		entry.toolResultOnly = false
		touchTranscriptEntry(entry)
		m.refreshViewport()
		return
	}
	m.addEntry(transcriptEntry{
		kind:           entryTool,
		title:          "tool",
		body:           formatToolResultBody(name, status, ""),
		isError:        isError,
		toolUseID:      strings.TrimSpace(toolUseID),
		toolName:       name,
		toolStatus:     status,
		toolResult:     content,
		toolExpanded:   isError,
		toolResultOnly: true,
		createdAt:      m.animationNow(),
	})
}

func (m *appModel) recordToolResultCitation(toolUseID, name, status, content string, isError bool) {
	cite := newToolResultCitation(toolUseID, name, status, content, isError)
	for entryIdx := len(m.transcript) - 1; entryIdx >= 0; entryIdx-- {
		entry := &m.transcript[entryIdx]
		if entry.kind == entryUser {
			break
		}
		if entry.kind != entryAssistant {
			continue
		}
		for citeIdx := len(entry.citations) - 1; citeIdx >= 0; citeIdx-- {
			if toolCitationMatchesResult(entry.citations[citeIdx], cite) {
				entry.citations[citeIdx].status = cite.status
				entry.citations[citeIdx].preview = cite.preview
				entry.citations[citeIdx].isError = cite.isError
				touchTranscriptEntry(entry)
				m.refreshViewport()
				return
			}
		}
	}
	if idx := m.lastAssistantCitationHostIndex(); idx >= 0 {
		m.transcript[idx].citations = append(m.transcript[idx].citations, cite)
		touchTranscriptEntry(&m.transcript[idx])
	} else {
		entry := transcriptEntry{
			kind:      entryAssistant,
			title:     "assistant",
			citations: []toolCitation{cite},
			createdAt: m.animationNow(),
		}
		touchTranscriptEntry(&entry)
		m.transcript = append(m.transcript, entry)
	}
	m.refreshViewport()
}

type toolEntryResult struct {
	toolUseID string
	name      string
	status    string
	isError   bool
}

func toolEntryMatchesResult(entry transcriptEntry, result toolEntryResult) bool {
	if !isToolTransaction(entry) || toolEntryStatus(entry) != "running" {
		return false
	}
	if entry.toolUseID != "" || result.toolUseID != "" {
		return entry.toolUseID != "" && entry.toolUseID == result.toolUseID
	}
	return strings.EqualFold(entry.toolName, result.name)
}

func toolCitationMatchesResult(running, result toolCitation) bool {
	if running.status != "running" {
		return false
	}
	if running.toolUseID != "" || result.toolUseID != "" {
		return running.toolUseID != "" && running.toolUseID == result.toolUseID
	}
	return strings.EqualFold(running.name, result.name)
}

func (m appModel) lastAssistantCitationHostIndex() int {
	for i := len(m.transcript) - 1; i >= 0; i-- {
		switch m.transcript[i].kind {
		case entryAssistant:
			return i
		case entryUser:
			return -1
		}
	}
	return -1
}

func assistantEntryIsRenderable(entry transcriptEntry) bool {
	if entry.kind != entryAssistant {
		return true
	}
	if sanitizeAssistantVisibleBody(sanitizeTerminalText(entry.body)) != "" {
		return true
	}
	for _, cite := range entry.citations {
		if strings.TrimSpace(cite.name) != "" {
			return true
		}
	}
	return false
}

// refreshViewport 将 transcript 重新渲染到 viewport，并滚动到底部。
func (m *appModel) refreshViewport() {
	content := m.renderTranscriptContent()
	if m.selectionActive {
		content = m.renderTranscriptSelection(content)
	}
	m.viewport.SetContent(content)
	if !m.selectionActive {
		m.viewport.GotoBottom()
	}
	m.markTranscriptRefreshed()
}

// refreshViewportPreservingOffset 刷新 transcript 内容，但保留用户当前滚动位置。
func (m *appModel) refreshViewportPreservingOffset() {
	offset := m.viewport.YOffset
	content := m.renderTranscriptContent()
	if m.selectionActive {
		content = m.renderTranscriptSelection(content)
	}
	m.viewport.SetContent(content)
	m.viewport.SetYOffset(offset)
	m.markTranscriptRefreshed()
}

func (m *appModel) refreshViewportForStreaming() {
	if m == nil {
		return
	}
	now := time.Now()
	if m.lastTranscriptRefreshAt.IsZero() || now.Sub(m.lastTranscriptRefreshAt) >= transcriptStreamingRefreshInterval {
		m.refreshViewport()
		return
	}
	m.transcriptRefreshPending = true
}

func (m *appModel) markTranscriptRefreshed() {
	if m == nil {
		return
	}
	m.transcriptRefreshPending = false
	m.lastTranscriptRefreshAt = time.Now()
}

func (m *appModel) renderTranscriptContent() string {
	return m.renderTranscriptContentAt(maxInt(20, m.viewport.Width), m.showThinking, m.animationNow())
}

func (m *appModel) renderTranscriptContentAt(width int, showThinking bool, at time.Time) string {
	if len(m.transcript) == 0 {
		m.transcriptRenderCache = nil
		return ""
	}
	if len(m.transcriptRenderCache) != len(m.transcript) {
		next := make([]transcriptRenderCacheEntry, len(m.transcript))
		copy(next, m.transcriptRenderCache)
		m.transcriptRenderCache = next
	}
	var renderedTranscript strings.Builder
	hasPrevious := false
	var previousKind entryKind
	for idx, entry := range m.transcript {
		if entry.kind == entryThinking && !showThinking {
			continue
		}
		if !assistantEntryIsRenderable(entry) {
			continue
		}
		key := transcriptRenderKey(entry, width)
		if m.transcriptRenderCache[idx].key == key {
			appendTranscriptRenderedEntry(&renderedTranscript, m.transcriptRenderCache[idx].rendered, entry.kind, previousKind, hasPrevious)
			previousKind = entry.kind
			hasPrevious = true
			continue
		}
		rendered := renderEntryAt(entry, width, at)
		if rendered == "" {
			continue
		}
		m.transcriptRenderCache[idx] = transcriptRenderCacheEntry{key: key, rendered: rendered}
		appendTranscriptRenderedEntry(&renderedTranscript, rendered, entry.kind, previousKind, hasPrevious)
		previousKind = entry.kind
		hasPrevious = true
	}
	return renderedTranscript.String()
}

func transcriptRenderKey(entry transcriptEntry, width int) transcriptRenderCacheKey {
	key := transcriptRenderCacheKey{
		kind:            entry.kind,
		renderMode:      entry.renderMode,
		title:           entry.title,
		inputTokens:     inputTokenSnapshot(entry.inputTokens),
		color:           entry.color,
		isError:         entry.isError,
		toolUseID:       entry.toolUseID,
		toolName:        entry.toolName,
		toolStatus:      entry.toolStatus,
		toolTarget:      entry.toolTarget,
		toolResultLen:   len(entry.toolResult),
		toolExpanded:    entry.toolExpanded,
		toolFocused:     entry.toolFocused,
		toolHovered:     entry.toolHovered,
		toolResultOnly:  entry.toolResultOnly,
		width:           width,
		version:         entry.version,
		bodyLen:         len(entry.body),
		citationCount:   len(entry.citations),
		createdAtUnixNS: entry.createdAt.UnixNano(),
		createdAtIsZero: entry.createdAt.IsZero(),
	}
	if entry.version == 0 {
		key.body = entry.body
		key.toolResult = entry.toolResult
		key.citations = transcriptCitationSnapshot(entry.citations)
	}
	return key
}

func inputTokenSnapshot(tokens []inputToken) string {
	if len(tokens) == 0 {
		return ""
	}
	var b strings.Builder
	for _, token := range tokens {
		b.WriteString(strconv.Itoa(int(token.Kind)))
		b.WriteByte(':')
		b.WriteString(strconv.Itoa(token.Start))
		b.WriteByte(':')
		b.WriteString(strconv.Itoa(token.End))
		b.WriteByte(':')
		b.WriteString(token.Label)
		b.WriteByte(':')
		if token.AutoSpace {
			b.WriteByte('1')
		} else {
			b.WriteByte('0')
		}
		b.WriteByte(';')
	}
	return b.String()
}

func transcriptCitationSnapshot(citations []toolCitation) string {
	if len(citations) == 0 {
		return ""
	}
	var b strings.Builder
	for _, cite := range citations {
		b.WriteString(cite.toolUseID)
		b.WriteByte('\x00')
		b.WriteString(cite.name)
		b.WriteByte('\x00')
		b.WriteString(cite.target)
		b.WriteByte('\x00')
		b.WriteString(cite.status)
		b.WriteByte('\x00')
		b.WriteString(cite.preview)
		b.WriteByte('\x00')
		if cite.isError {
			b.WriteByte('1')
		} else {
			b.WriteByte('0')
		}
		b.WriteByte('\x00')
	}
	return b.String()
}

// renderTranscript 把多条 transcript 记录渲染为 viewport 内容。
func renderTranscript(entries []transcriptEntry, width int, showThinking bool) string {
	return renderTranscriptAt(entries, width, showThinking, time.Time{})
}

func renderTranscriptAt(entries []transcriptEntry, width int, showThinking bool, at time.Time) string {
	if len(entries) == 0 {
		return ""
	}
	var renderedTranscript strings.Builder
	hasPrevious := false
	var previousKind entryKind
	for _, entry := range entries {
		if entry.kind == entryThinking && !showThinking {
			continue
		}
		if !assistantEntryIsRenderable(entry) {
			continue
		}
		rendered := renderEntryAt(entry, width, at)
		if rendered == "" {
			continue
		}
		appendTranscriptRenderedEntry(&renderedTranscript, rendered, entry.kind, previousKind, hasPrevious)
		previousKind = entry.kind
		hasPrevious = true
	}
	return renderedTranscript.String()
}

func appendTranscriptRenderedEntry(builder *strings.Builder, rendered string, currentKind, previousKind entryKind, hasPrevious bool) {
	rendered = strings.TrimRight(rendered, "\n")
	if rendered == "" {
		return
	}
	if hasPrevious {
		builder.WriteString(transcriptEntrySeparator(previousKind, currentKind))
	}
	builder.WriteString(rendered)
}

func transcriptEntrySeparator(previousKind, currentKind entryKind) string {
	if currentKind == entryTool && (previousKind == entryAssistant || previousKind == entryTool) {
		return "\n"
	}
	return "\n\n"
}

// renderEntry 渲染一条带标签和统一缩进的 transcript 记录。
func renderEntry(entry transcriptEntry, width int) string {
	return renderEntryAt(entry, width, time.Time{})
}

func renderEntryAt(entry transcriptEntry, width int, at time.Time) string {
	title := sanitizeTerminalText(entry.title)
	color := sanitizeTerminalText(entry.color)
	var label string
	if color != "" {
		label = lipgloss.NewStyle().Foreground(lipgloss.Color(color)).Bold(true).Render(title)
	} else {
		label = labelStyle(entry.kind).Render(title)
	}
	bodyWidth := transcriptBodyWidth(width)
	body := renderEntryBodyAt(entry, bodyWidth, at)
	if entry.kind == entryTool {
		if body == "" {
			return ""
		}
		return indentLines(body, transcriptEntryGutter)
	}
	if body == "" {
		return transcriptEntryGutter + label
	}
	return indentLines(label+"\n"+body, transcriptEntryGutter)
}

func transcriptBodyWidth(width int) int {
	return maxInt(1, width-lipgloss.Width(transcriptEntryGutter))
}

// renderEntryBody 按消息类型渲染正文，assistant 消息会走 Markdown 渲染。
func renderEntryBody(entry transcriptEntry, width int) string {
	return renderEntryBodyAt(entry, width, time.Time{})
}

func renderEntryBodyAt(entry transcriptEntry, width int, at time.Time) string {
	if isToolTransaction(entry) {
		return renderToolTransactionEntry(entry, width)
	}
	body := entry.body
	if entry.kind != entryUser {
		body = sanitizeTerminalText(body)
	}
	body = strings.TrimRight(body, "\n")
	if entry.kind == entryAssistant {
		body = sanitizeAssistantVisibleBody(body)
		if entry.renderMode != transcriptRenderFormatted {
			return bodyStyle.Width(width).Render(body)
		}
		return renderAssistantBodyWithCitations(body, width, entry.citations)
	}
	if body == "" {
		return ""
	}
	if entry.kind == entryUser && len(entry.inputTokens) > 0 {
		return renderTokenizedTranscriptBody(body, entry.inputTokens, width)
	}
	if entry.kind == entryThinking {
		return thinkingBodyStyle.Width(width).Render(body)
	}
	if entry.kind == entryTool {
		isError := entry.isError
		isResult := toolEntryHasCompletedStatus(entry)
		switch {
		case isError:
			return renderToolEntryBodyWithMarker(body, width, 1, toolErrorBorderStyle, "!")
		case isResult:
			return renderToolEntryBodyWithMarker(body, width, 1, toolResultBorderStyle, "✓")
		default:
			return renderToolEntryBody(body, width, 1)
		}
	}
	return bodyStyle.Width(width).Render(body)
}

func toolEntryHasCompletedStatus(entry transcriptEntry) bool {
	if status := toolEntryStatus(entry); status != "" {
		return status != "running" && status != "error"
	}
	line := firstToolEntryLine(entry.body)
	parts := splitToolSummaryParts(line)
	return len(parts) >= 2 && strings.EqualFold(parts[1], "ok")
}

func isToolTransaction(entry transcriptEntry) bool {
	return entry.kind == entryTool &&
		(entry.toolName != "" || entry.toolUseID != "" || entry.toolStatus != "" || entry.title == "tool")
}

func toolEntryStatus(entry transcriptEntry) string {
	status := strings.ToLower(strings.TrimSpace(entry.toolStatus))
	switch status {
	case "running", "ok", "error":
		return status
	}
	if entry.isError {
		return "error"
	}
	parts := splitToolSummaryParts(firstToolEntryLine(entry.body))
	if len(parts) >= 2 {
		switch strings.ToLower(parts[1]) {
		case "running", "ok", "error":
			return strings.ToLower(parts[1])
		}
	}
	return "ok"
}

func toolEntryDisplayName(entry transcriptEntry) string {
	name := strings.TrimSpace(entry.toolName)
	if name == "" {
		parts := splitToolSummaryParts(firstToolEntryLine(entry.body))
		if len(parts) > 0 {
			name = parts[0]
		}
	}
	if name == "" && entry.title != "tool" {
		name = strings.TrimSpace(entry.title)
	}
	if name == "" {
		name = "tool"
	}
	return name
}

func renderToolTransactionEntry(entry transcriptEntry, width int) string {
	status := toolEntryStatus(entry)
	borderStyle := toolResultBorderStyle
	switch status {
	case "running":
		borderStyle = toolCallBorderStyle
	case "error":
		borderStyle = toolErrorBorderStyle
	}
	if entry.toolHovered && !entry.toolFocused {
		borderStyle = borderStyle.
			BorderStyle(lipgloss.Border{Left: "┃"}).
			BorderLeft(true)
	}

	contentWidth := toolEntryContentWidth(width, borderStyle)
	innerWidth := maxInt(1, contentWidth-borderStyle.GetHorizontalFrameSize())
	summary := renderCompactToolSummary(entry, innerWidth)
	if entry.toolFocused {
		summary = toolFocusedStyle.Width(innerWidth).Render(summary)
	}

	if status == "running" || !entry.toolExpanded {
		return borderStyle.Width(contentWidth).Render(summary)
	}

	result := sanitizeTerminalText(entry.toolResult)
	result = strings.TrimRight(result, "\n")
	if result == "" {
		result = "(empty result)"
	}
	detailLines := limitRenderedDetailLines(strings.Split(result, "\n"), maxRenderedToolDetailLines)
	detailWidth := maxInt(1, innerWidth-2)
	detail := renderToolDetailLines(detailLines, detailWidth)
	return borderStyle.Width(contentWidth).Render(summary + "\n" + detail)
}

func renderCompactToolSummary(entry transcriptEntry, width int) string {
	width = maxInt(1, width)
	status := toolEntryStatus(entry)
	icon := "✓"
	statusText := "ok"
	statusStyle := toolCitationOKStyle
	nameStyle := toolHeaderStyle
	targetStyle := toolCitationStyle
	switch status {
	case "running":
		icon = "◌"
		statusText = "running"
		statusStyle = toolHeaderStyle
	case "error":
		icon = "×"
		statusText = "error"
		statusStyle = toolCitationErrorStyle
	}
	if entry.toolHovered && !entry.toolFocused {
		statusStyle = statusStyle.Underline(true)
		nameStyle = nameStyle.Underline(true)
		targetStyle = targetStyle.Underline(true)
	}

	name := strings.Join(strings.Fields(sanitizeTerminalText(toolEntryDisplayName(entry))), " ")
	target := strings.Join(strings.Fields(sanitizeTerminalText(entry.toolTarget)), " ")
	if name == "" {
		name = "tool"
	}

	focusPrefix := ""
	if entry.toolFocused {
		focusPrefix = "› "
	}
	iconText := icon + " "
	statusSuffix := " · " + statusText
	nameWidth := lipgloss.Width(name)
	baseWidth := lipgloss.Width(focusPrefix) + lipgloss.Width(iconText) + nameWidth
	statusWidth := lipgloss.Width(statusSuffix)

	showStatus := true
	targetText := ""
	if target != "" {
		targetBudget := width - baseWidth - statusWidth - 1
		if targetBudget >= 1 {
			targetText = truncateDisplayWidth(target, targetBudget)
		} else {
			showStatus = false
			targetBudget = width - baseWidth - 1
			if targetBudget >= 1 {
				targetText = truncateDisplayWidth(target, targetBudget)
			}
		}
	} else if baseWidth+statusWidth > width {
		showStatus = false
	}

	fixedWidth := lipgloss.Width(focusPrefix) + lipgloss.Width(iconText)
	if targetText != "" {
		fixedWidth += 1 + lipgloss.Width(targetText)
	}
	if showStatus {
		fixedWidth += statusWidth
	}
	if fixedWidth+nameWidth > width {
		name = truncateDisplayWidth(name, maxInt(1, width-fixedWidth))
	}

	var line strings.Builder
	line.WriteString(focusPrefix)
	line.WriteString(statusStyle.Render(iconText))
	line.WriteString(nameStyle.Render(name))
	if targetText != "" {
		line.WriteString(targetStyle.Render(" " + targetText))
	}
	if showStatus {
		line.WriteString(statusStyle.Render(statusSuffix))
	}
	return truncateStyledDisplayWidth(line.String(), width)
}

func truncateStyledDisplayWidth(text string, width int) string {
	if lipgloss.Width(text) <= width {
		return text
	}
	return ansi.Truncate(text, maxInt(1, width), "")
}

func renderAssistantBodyWithCitations(body string, width int, citations []toolCitation) string {
	citations = compactToolCitations(citations)
	rendered := renderMarkdown(body, width)
	if len(citations) == 0 {
		return rendered
	}
	quote := renderToolCitationQuote(citations, width)
	if quote == "" {
		return rendered
	}
	if rendered == "" {
		return quote
	}
	return rendered + "\n" + quote
}

func newToolCallCitation(toolUseID, name string, input json.RawMessage) toolCitation {
	name = strings.TrimSpace(name)
	if name == "" {
		name = "tool"
	}
	fields := toolInputFields(input)
	return toolCitation{
		toolUseID: strings.TrimSpace(toolUseID),
		name:      name,
		target:    primaryToolInput(name, fields),
		status:    "running",
	}
}

func newToolResultCitation(toolUseID, name, status, content string, isError bool) toolCitation {
	name = strings.TrimSpace(name)
	if name == "" {
		name = "tool"
	}
	status = strings.TrimSpace(status)
	if status == "" {
		status = "ok"
	}
	return toolCitation{
		toolUseID: strings.TrimSpace(toolUseID),
		name:      name,
		status:    status,
		preview:   summarizeToolContent(content),
		isError:   isError,
	}
}

func compactToolCitations(citations []toolCitation) []toolCitation {
	out := make([]toolCitation, 0, len(citations))
	for _, cite := range citations {
		cite.name = strings.TrimSpace(cite.name)
		cite.target = strings.TrimSpace(cite.target)
		cite.status = strings.TrimSpace(cite.status)
		cite.preview = strings.TrimSpace(cite.preview)
		if cite.name == "" {
			continue
		}
		if cite.status == "" {
			cite.status = "ok"
		}
		out = append(out, cite)
	}
	return out
}

func renderToolCitationQuote(citations []toolCitation, width int) string {
	lines := make([]string, 0, len(citations))
	contentWidth := maxInt(1, width-2)
	for _, cite := range citations {
		if line := renderToolCitationQuoteLine(cite, contentWidth); line != "" {
			lines = append(lines, toolCitationQuoteBorderStyle.Render("│")+" "+line)
		}
	}
	if len(lines) == 0 {
		return ""
	}
	return strings.Join(lines, "\n")
}

func renderToolCitationQuoteLine(cite toolCitation, width int) string {
	name := strings.TrimSpace(sanitizeTerminalText(cite.name))
	if name == "" {
		return ""
	}
	key := toolCitationKeyStyle.Render("[" + name + "]")
	status := toolCitationStatusStyle(cite).Render(toolCitationStatusText(cite))
	target := strings.TrimSpace(sanitizeTerminalText(cite.target))
	lineWidth := lipgloss.Width("["+name+"] ") + lipgloss.Width(toolCitationStatusText(cite))
	if target == "" {
		return key + " " + status
	}
	targetWidth := maxInt(1, width-lineWidth-lipgloss.Width(" · "))
	return key + " " + status + toolCitationStyle.Render(" · "+truncateDisplayWidth(target, targetWidth))
}

func toolCitationStatusText(cite toolCitation) string {
	switch {
	case cite.isError || strings.EqualFold(cite.status, "error"):
		return "error"
	case strings.EqualFold(cite.status, "running"):
		return "running"
	default:
		return "ok"
	}
}

func toolCitationStatusStyle(cite toolCitation) lipgloss.Style {
	if cite.isError || strings.EqualFold(cite.status, "error") {
		return toolCitationErrorStyle
	}
	if strings.EqualFold(cite.status, "running") {
		return toolCitationStyle
	}
	return toolCitationOKStyle
}

// renderToolEntryBodyWithStyle renders a tool entry in blockquote style using the given border style.
func renderToolEntryBodyWithStyle(body string, width int, progress float64, borderStyle lipgloss.Style) string {
	return renderToolEntryBodyWithMarker(body, width, progress, borderStyle, "▸")
}

func renderToolEntryBodyWithMarker(body string, width int, progress float64, borderStyle lipgloss.Style, marker string) string {
	body = strings.TrimRight(body, "\n")
	summary, detail := splitToolSummary(body)
	contentWidth := toolEntryContentWidth(width, borderStyle)
	headerStyle := toolHeaderStyle
	switch marker {
	case "✓":
		headerStyle = lipgloss.NewStyle().Foreground(colorManager.LipglossColor(colorLabelResult)).Bold(true)
	case "!":
		headerStyle = lipgloss.NewStyle().Foreground(colorManager.LipglossColor(colorLabelError)).Bold(true)
	}
	header := headerStyle.Render(marker + " " + summary)

	if detail == "" || progress <= 0 {
		return borderStyle.Width(contentWidth).Render(header)
	}

	detailLines := limitRenderedDetailLines(strings.Split(detail, "\n"), maxRenderedToolDetailLines)
	visibleLines := maxInt(1, int(float64(len(detailLines))*progress+0.999))
	if visibleLines > len(detailLines) {
		visibleLines = len(detailLines)
	}
	detailWidth := maxInt(1, contentWidth-borderStyle.GetHorizontalFrameSize())
	content := header + "\n" + renderToolDetailLines(detailLines[:visibleLines], detailWidth)
	return borderStyle.Width(contentWidth).Render(content)
}

func toolEntryContentWidth(width int, borderStyle lipgloss.Style) int {
	return maxInt(1, width-borderStyle.GetHorizontalFrameSize()-toolEntryNoWrapSafetyCells)
}

const toolEntryNoWrapSafetyCells = transcriptPanelHorizontalFrame + 1

func limitRenderedDetailLines(lines []string, maxLines int) []string {
	if maxLines <= 0 || len(lines) <= maxLines {
		return lines
	}
	if maxLines == 1 {
		return []string{"... " + strconv.Itoa(len(lines)) + " lines hidden"}
	}
	visible := maxLines - 1
	hidden := len(lines) - visible
	out := append([]string(nil), lines[:visible]...)
	out = append(out, "... "+strconv.Itoa(hidden)+" more lines hidden")
	return out
}

func renderToolDetailLines(lines []string, width int) string {
	containsUnifiedDiffHunk := hasUnifiedDiffHunk(lines)
	diffRowWidth := diffDetailRowsWidth(lines, width)
	rendered := make([]string, 0, len(lines))
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		style := toolDetailStyle
		renderedLine := "  " + trimmed
		isDiffLine := false
		switch {
		case containsUnifiedDiffHunk && isUnifiedDiffMetadataLine(trimmed):
			style = toolCitationStyle
		case diffDetailLineMarker(line, containsUnifiedDiffHunk) == "+":
			style = lipgloss.NewStyle().
				Foreground(lipgloss.Color("194")).
				Background(lipgloss.Color("22")).
				Bold(true)
			renderedLine = strings.TrimRight(line, " \t\r")
			isDiffLine = true
		case diffDetailLineMarker(line, containsUnifiedDiffHunk) == "-":
			style = lipgloss.NewStyle().
				Foreground(lipgloss.Color("224")).
				Background(lipgloss.Color("52")).
				Bold(true)
			renderedLine = strings.TrimRight(line, " \t\r")
			isDiffLine = true
		}
		if isDiffLine {
			renderedLine = padDisplayWidth(truncateDisplayWidth(renderedLine, diffRowWidth), diffRowWidth)
			rendered = append(rendered, style.Render(renderedLine))
			continue
		}
		renderedLine = truncateDisplayWidth(renderedLine, width)
		rendered = append(rendered, style.Width(width).Render(renderedLine))
	}
	return strings.Join(rendered, "\n")
}

func diffDetailRowsWidth(_ []string, width int) int {
	return maxInt(1, width)
}

func hasUnifiedDiffHunk(lines []string) bool {
	for _, line := range lines {
		if strings.HasPrefix(strings.TrimSpace(line), "@@ ") {
			return true
		}
	}
	return false
}

func isUnifiedDiffMetadataLine(line string) bool {
	return strings.HasPrefix(line, "@@ ") || strings.HasPrefix(line, "--- ") || strings.HasPrefix(line, "+++ ")
}

func diffDetailLineMarker(line string, allowStandalone bool) string {
	if allowStandalone && strings.HasPrefix(line, "+") {
		return "+"
	}
	if allowStandalone && strings.HasPrefix(line, "-") {
		return "-"
	}
	fields := strings.Fields(line)
	if len(fields) < 3 || !isDecimalNumber(fields[0]) {
		return ""
	}
	switch fields[1] {
	case "+", "-":
		if fields[2] == "│" {
			return fields[1]
		}
		return ""
	default:
		return ""
	}
}

func isDecimalNumber(value string) bool {
	if value == "" {
		return false
	}
	for _, r := range value {
		if r < '0' || r > '9' {
			return false
		}
	}
	return true
}

// renderToolEntryBody renders a tool call entry with the default orange border.
// Called from renderEntryBodyAt for the "tool" title.
func renderToolEntryBody(body string, width int, progress float64) string {
	return renderToolEntryBodyWithStyle(body, width, progress, toolCallBorderStyle)
}

func splitToolSummary(body string) (string, string) {
	lines := strings.Split(strings.TrimRight(body, "\n"), "\n")
	if len(lines) == 0 {
		return "", ""
	}
	summary := strings.TrimSpace(lines[0])
	if len(lines) == 1 {
		return summary, ""
	}
	return summary, strings.Join(lines[1:], "\n")
}

// labelStyle 根据消息类型选择左侧标签样式。
func labelStyle(kind entryKind) lipgloss.Style {
	switch kind {
	case entryUser:
		return labelUserStyle
	case entryAssistant:
		return labelAssistantStyle
	case entryThinking:
		return labelThinkingStyle
	case entryTool:
		return labelToolStyle
	case entryError:
		return labelErrorStyle
	default:
		return labelSystemStyle
	}
}

// turnsCount 返回当前会话的用户消息轮次数。
func (m appModel) turnsCount() int {
	n := 0
	for _, e := range m.transcript {
		if e.kind == entryUser && e.title == "you" {
			n++
		}
	}
	return n
}

// indentLines 给多行文本逐行添加固定前缀。
func indentLines(text, prefix string) string {
	lines := strings.Split(text, "\n")
	for i, line := range lines {
		lines[i] = prefix + line
	}
	return strings.Join(lines, "\n")
}

package bubble

import (
	"strings"
	"unicode"
	"unicode/utf8"

	"github.com/charmbracelet/x/ansi"
)

const streamTabWidth = 4

type terminalTextSanitizer struct {
	utf8Tail  []byte
	ansiTail  []byte
	pendingCR bool
}

func (s *terminalTextSanitizer) Push(text string) string {
	if text == "" && len(s.utf8Tail) == 0 {
		return ""
	}
	data := make([]byte, 0, len(s.utf8Tail)+len(text))
	data = append(data, s.utf8Tail...)
	data = append(data, text...)

	valid, tail := normalizeUTF8Bytes(data, false)
	s.utf8Tail = tail
	return s.consume(valid)
}

func (s *terminalTextSanitizer) Flush() string {
	var out strings.Builder
	if len(s.utf8Tail) > 0 {
		valid, _ := normalizeUTF8Bytes(s.utf8Tail, true)
		s.utf8Tail = nil
		out.WriteString(s.consume(valid))
	}
	s.ansiTail = nil
	if s.pendingCR {
		out.WriteByte('\n')
		s.pendingCR = false
	}
	return out.String()
}

func (s *terminalTextSanitizer) Reset() {
	s.utf8Tail = nil
	s.ansiTail = nil
	s.pendingCR = false
}

func (s *terminalTextSanitizer) consume(text string) string {
	text = expandC1Controls(text)
	if len(s.ansiTail) > 0 {
		data := make([]byte, 0, len(s.ansiTail)+len(text))
		data = append(data, s.ansiTail...)
		data = append(data, text...)
		text = string(data)
		s.ansiTail = nil
	}
	var out strings.Builder
	for len(text) > 0 {
		seq, _, n, next := ansi.DecodeSequence(text, ansi.NormalState, nil)
		if n <= 0 {
			// Malformed terminal sequences must not stall the stream or leak
			// their current byte into the visible transcript.
			text = text[1:]
			continue
		}
		text = text[n:]

		if next != ansi.NormalState {
			s.ansiTail = append(s.ansiTail[:0], seq...)
			s.ansiTail = append(s.ansiTail, text...)
			break
		}
		if !isDisplaySequence(seq) {
			continue
		}

		r, _ := utf8.DecodeRuneInString(seq)
		switch r {
		case '\r':
			if s.pendingCR {
				out.WriteByte('\n')
			}
			s.pendingCR = true
		case '\n':
			out.WriteByte('\n')
			s.pendingCR = false
		case '\t':
			s.flushPendingCR(&out)
			out.WriteByte('\t')
		default:
			s.flushPendingCR(&out)
			out.WriteString(seq)
		}
	}
	return out.String()
}

func expandC1Controls(text string) string {
	var out strings.Builder
	for _, r := range text {
		if r >= 0x80 && r <= 0x9f {
			out.WriteByte('\x1b')
			out.WriteRune(r - 0x40)
			continue
		}
		out.WriteRune(r)
	}
	return out.String()
}

func (s *terminalTextSanitizer) flushPendingCR(out *strings.Builder) {
	if !s.pendingCR {
		return
	}
	out.WriteByte('\n')
	s.pendingCR = false
}

func normalizeUTF8Bytes(data []byte, final bool) (string, []byte) {
	var out strings.Builder
	for len(data) > 0 {
		if !utf8.FullRune(data) {
			if !final {
				return out.String(), append([]byte(nil), data...)
			}
			out.WriteRune(utf8.RuneError)
			data = data[1:]
			continue
		}
		r, size := utf8.DecodeRune(data)
		if r == utf8.RuneError && size == 1 {
			out.WriteRune(utf8.RuneError)
			data = data[1:]
			continue
		}
		out.Write(data[:size])
		data = data[size:]
	}
	return out.String(), nil
}

func isDisplaySequence(seq string) bool {
	if seq == "" {
		return false
	}
	r, _ := utf8.DecodeRuneInString(seq)
	switch r {
	case '\r', '\n', '\t':
		return true
	}
	return !unicode.IsControl(r)
}

type displayToken struct {
	text  string
	width int
	kind  displayTokenKind
}

type displayTokenKind uint8

const (
	displayTokenText displayTokenKind = iota
	displayTokenNewline
	displayTokenTab
)

type streamLineBuffer struct {
	sanitizer   terminalTextSanitizer
	pending     string
	clusterTail string
	column      int
	width       int
	hasContent  bool
}

func (b *streamLineBuffer) Push(delta string, width int) string {
	width = maxInt(1, width)
	var out strings.Builder
	if b.width != 0 && b.width != width {
		out.WriteString(b.Resize(width))
	}
	b.width = width

	safe := b.sanitizer.Push(delta)
	if safe != "" {
		b.hasContent = true
		out.WriteString(b.accept(safe, width, false))
	}
	return out.String()
}

func (b *streamLineBuffer) Resize(width int) string {
	width = maxInt(1, width)
	b.width = width
	hidden := b.pending + b.clusterTail
	b.pending = ""
	b.clusterTail = ""
	b.column = 0
	if hidden == "" {
		return ""
	}
	return b.accept(hidden, width, false)
}

func (b *streamLineBuffer) Flush(width int) string {
	width = maxInt(1, width)
	var out strings.Builder
	if b.width != 0 && b.width != width {
		out.WriteString(b.Resize(width))
	}
	b.width = width

	safe := b.sanitizer.Flush()
	out.WriteString(b.accept(safe, width, true))
	if b.clusterTail != "" {
		out.WriteString(b.accept(b.clusterTail, width, true))
		b.clusterTail = ""
	}
	if b.pending != "" {
		out.WriteString(b.pending)
	}
	b.Reset()
	return out.String()
}

func (b *streamLineBuffer) Reset() {
	b.sanitizer.Reset()
	b.pending = ""
	b.clusterTail = ""
	b.column = 0
	b.width = 0
	b.hasContent = false
}

func (b *streamLineBuffer) HasContent() bool {
	return b.hasContent
}

func (b *streamLineBuffer) accept(text string, width int, final bool) string {
	if text == "" && b.clusterTail == "" {
		return ""
	}
	tokens := displayTokens(b.clusterTail + text)
	b.clusterTail = ""
	if !final && len(tokens) > 0 && tokens[len(tokens)-1].kind == displayTokenText {
		b.clusterTail = tokens[len(tokens)-1].text
		tokens = tokens[:len(tokens)-1]
	}

	var out strings.Builder
	for _, token := range tokens {
		switch token.kind {
		case displayTokenNewline:
			out.WriteString(b.pending)
			out.WriteByte('\n')
			b.pending = ""
			b.column = 0
		case displayTokenTab:
			spaces := streamTabWidth - b.column%streamTabWidth
			for range spaces {
				b.appendToken(&out, " ", 1, width)
			}
		default:
			b.appendToken(&out, token.text, token.width, width)
		}
	}
	return out.String()
}

func (b *streamLineBuffer) appendToken(out *strings.Builder, text string, tokenWidth, width int) {
	if tokenWidth > 0 && b.column > 0 && b.column+tokenWidth > width {
		out.WriteString(b.pending)
		b.pending = ""
		b.column = 0
	}
	b.pending += text
	b.column += maxInt(0, tokenWidth)
	if b.column >= width {
		out.WriteString(b.pending)
		b.pending = ""
		b.column = 0
	}
}

func displayTokens(text string) []displayToken {
	tokens := make([]displayToken, 0, len(text))
	for remaining := text; remaining != ""; {
		cluster, width := terminalFirstGraphemeCluster(remaining)
		remaining = remaining[len(cluster):]
		token := displayToken{text: cluster, width: width, kind: displayTokenText}
		switch cluster {
		case "\n":
			token.kind = displayTokenNewline
		case "\t":
			token.kind = displayTokenTab
		}
		tokens = append(tokens, token)
	}
	return tokens
}

func sanitizeTerminalText(text string) string {
	var sanitizer terminalTextSanitizer
	safe := sanitizer.Push(text) + sanitizer.Flush()
	return expandDisplayTabs(safe)
}

func expandDisplayTabs(text string) string {
	if !strings.ContainsRune(text, '\t') {
		return text
	}
	var out strings.Builder
	column := 0
	for _, token := range displayTokens(text) {
		switch token.kind {
		case displayTokenNewline:
			out.WriteByte('\n')
			column = 0
		case displayTokenTab:
			spaces := streamTabWidth - column%streamTabWidth
			out.WriteString(strings.Repeat(" ", spaces))
			column += spaces
		default:
			out.WriteString(token.text)
			column += maxInt(0, token.width)
		}
	}
	return out.String()
}

// 本文件定义输入框提交、斜杠命令、终端模式和历史输入导航行为。
package bubble

import (
	"github.com/charmbracelet/bubbles/textarea"
	tea "github.com/charmbracelet/bubbletea"
	"strings"
	"time"
)

// handleSubmit 处理 Enter 提交，根据输入内容分派到聊天、命令或终端执行路径。
func (m appModel) handleSubmit() (tea.Model, tea.Cmd) {
	m.reconcileLegacyRunningState()
	var line string
	var ok bool
	m, line, ok = m.consumeSubmittedInput()
	if !ok {
		return m, nil
	}
	m.restoreMainTranscriptFromSubagentPreview()

	if isExitCommandInput(line) {
		m.rememberInputHistory(line)
		_, cmd := m.handleCommand(line)
		return m, cmd
	}
	if line == "!" {
		m.toggleTerminalMode()
		return m, nil
	}
	if m.terminalMode {
		m.rememberInputHistory(line)
		return m.submitShellCommand(line)
	}
	if command, ok := shellCommandFromBang(line); ok {
		if m.isWorkRunning() {
			m.addEntry(transcriptEntry{kind: entrySystem, title: "busy", body: "terminal commands are unavailable while a turn is running"})
			return m, nil
		}
		m.rememberInputHistory(line)
		return m.submitShellCommand(command)
	}

	if rewritten, ok := m.rewriteSlashSkillInput(line); ok {
		line = rewritten
	} else {
		if handled, cmd := m.handleCommand(line); handled {
			return m, cmd
		}
	}

	if m.isModelWorkRunning() {
		return m.submitSupplement(line), nil
	}
	if m.isTerminalWorkRunning() {
		m.addEntry(transcriptEntry{kind: entrySystem, title: "busy", body: "chat is unavailable while a terminal command is running"})
		return m, nil
	}

	m.rememberInputHistory(line)
	return m.startChatTurn(line)
}

func (m appModel) rewriteSlashSkillInput(line string) (string, bool) {
	trimmed := strings.TrimSpace(line)
	if !strings.HasPrefix(trimmed, "/") {
		return "", false
	}
	token := commandToken(trimmed)
	if token == "" || token == "/" {
		return "", false
	}
	if m.commandRegistry != nil {
		if _, ok := m.commandRegistry.Lookup(token); ok {
			return "", false
		}
	}
	ref, ok := m.slashSkillReference(token)
	if !ok {
		return "", false
	}
	args := strings.TrimSpace(strings.TrimPrefix(trimmed, token))
	if args == "" {
		return ref, true
	}
	return ref + " " + args, true
}

func (m appModel) handleQueueSubmit() (tea.Model, tea.Cmd) {
	var line string
	var ok bool
	m, line, ok = m.consumeSubmittedInput()
	if !ok {
		return m, nil
	}
	if m.isModelWorkRunning() {
		return m.queueChatInput(line), nil
	}
	draft := m.submittedDraft
	if strings.TrimSpace(draft.Text) != line {
		draft = inputDraft{Text: line}
	}
	m.setInputDraft(draft)
	m.inputPasteFoldActive = false
	m.syncInputMode()
	m.relayout()
	return m, nil
}

func (m appModel) consumeSubmittedInput() (appModel, string, bool) {
	draft := trimInputDraft(m.currentInputDraft())
	if draft.Text == "" {
		return m, "", false
	}
	m.input.Reset()
	m.inputTokens = nil
	m.inputPasteFoldActive = false
	m.resetHistoryNavigation()
	m.syncInputMode()
	m.relayout()

	if continued, text := stripContinuationDraft(draft); continued {
		m.submittedDraft = cloneInputDraft(draft)
		m.rememberInputHistory(draft.Text)
		m.pending = append(m.pending, text)
		m.refreshViewport()
		return m, "", false
	}

	if len(m.pending) > 0 {
		m.pending = append(m.pending, draft)
		draft = joinInputDrafts(m.pending, "\n")
		m.pending = nil
	}
	m.submittedDraft = cloneInputDraft(draft)
	return m, draft.Text, true
}

// handleCommand 处理内置 TUI 命令。除 exit/quit 外，命令仍要求以斜杠开头。
func (m *appModel) handleCommand(line string) (bool, tea.Cmd) {
	trimmed := strings.TrimSpace(line)
	if !strings.HasPrefix(trimmed, "/") && !isBareExitCommand(trimmed) {
		return false, nil
	}
	if m.commandRegistry == nil {
		m.commandRegistry = NewCommandRegistry()
	}
	return m.commandRegistry.Dispatch(m, line)
}

func isExitCommandInput(line string) bool {
	trimmed := strings.TrimSpace(line)
	return trimmed == "/exit" || trimmed == "/quit" || isBareExitCommand(trimmed)
}

func isBareExitCommand(line string) bool {
	return line == "exit" || line == "quit"
}

// toggleTerminalMode 切换持续终端模式，并在 transcript 中写入状态提示。
func (m *appModel) toggleTerminalMode() {
	m.terminalMode = !m.terminalMode
	m.pending = nil
	m.activeAssistant = -1
	m.applyCursorAnimation()
	state := "terminal mode disabled"
	if m.terminalMode {
		state = "terminal mode enabled"
	}
	m.addEntry(transcriptEntry{
		kind:  entrySystem,
		title: "terminal",
		body:  state,
	})
}

// isTerminalInputActive 判断当前输入框是否需要展示终端模式视觉状态。
func (m appModel) isTerminalInputActive() bool {
	return m.terminalMode || m.terminalPreview
}

// hasMultilineInput 判断当前输入是否处于多行输入或续行状态。
func (m appModel) hasMultilineInput() bool {
	return len(m.pending) > 0 || strings.Contains(m.input.Value(), "\n")
}

// syncInputMode 根据当前文本同步一次性终端预览状态。
func (m *appModel) syncInputMode() {
	m.terminalPreview = hasBangPrefix(m.input.Value())
}

// handleInputVerticalNavigation 让上下键先在多行文本内移动，抵达边界后再切换历史输入。
func (m appModel) handleInputVerticalNavigation(direction int) (tea.Model, tea.Cmd) {
	if m.isTerminalWorkRunning() {
		return m, nil
	}

	if direction < 0 {
		if canMoveTextareaUp(m.input) {
			return m.updateInputWithKey(tea.KeyMsg{Type: tea.KeyUp})
		}
		if !textareaCursorAtStart(m.input) {
			m.input.CursorStart()
			m.syncInputMode()
			m.applyCursorAnimation()
			return m, nil
		}
		return m.handleHistoryNavigation(-1)
	}

	if canMoveTextareaDown(m.input) {
		return m.updateInputWithKey(tea.KeyMsg{Type: tea.KeyDown})
	}
	if !textareaCursorAtEnd(m.input) {
		m.input.CursorEnd()
		m.historyDownLock = false
		m.syncInputMode()
		m.applyCursorAnimation()
		return m, nil
	}
	if m.historyDownLock && m.historyIndex != -1 {
		m.historyDownLock = false
		return m, nil
	}
	return m.handleHistoryNavigation(1)
}

func (m appModel) submitSupplement(line string) appModel {
	line = strings.TrimSpace(line)
	if line == "" {
		return m
	}
	m.rememberInputHistory(line)
	submitter, ok := m.runner.(SupplementSubmitter)
	if !ok || !submitter.SubmitSupplement(line) {
		m.addEntry(transcriptEntry{
			kind:  entrySystem,
			title: "supplement",
			body:  "runner does not support running-turn supplements",
		})
		return m
	}
	m.addEntry(transcriptEntry{
		kind:        entryUser,
		title:       "you (supplement)",
		body:        line,
		inputTokens: m.submittedTokensForLine(line),
	})
	return m
}

func (m appModel) submittedTokensForLine(line string) []inputToken {
	draft := trimInputDraft(m.submittedDraft)
	if draft.Text != strings.TrimSpace(line) {
		return nil
	}
	return cloneInputTokens(draft.Tokens)
}

func (m appModel) userTranscriptEntry(title, line string) transcriptEntry {
	return transcriptEntry{
		kind:        entryUser,
		title:       title,
		body:        strings.TrimSpace(line),
		inputTokens: m.submittedTokensForLine(line),
	}
}

// startChatTurn records and starts a model turn when the guard is idle.
func (m appModel) startChatTurn(line string) (appModel, tea.Cmd) {
	line = strings.TrimSpace(line)
	if line == "" {
		return m, nil
	}
	if !m.queryGuard.StartModel() {
		m.addEntry(transcriptEntry{kind: entrySystem, title: "busy", body: "assistant is already running"})
		return m, nil
	}
	m.resetStreamingBuffers()
	m.addEntry(m.userTranscriptEntry("you", line))
	m.turnStartedAt = time.Now()
	m.syncRunningFlags()
	return m, runTurnCmd(m.ctx, m.runner, line)
}

// queueChatInput records a chat input for FIFO execution after the active turn.
func (m appModel) queueChatInput(line string) appModel {
	line = strings.TrimSpace(line)
	if line == "" {
		return m
	}
	m.rememberInputHistory(line)
	if m.chatQueue.Enqueue(line) {
		m.addEntry(m.userTranscriptEntry("you (queued)", line))
		m.addEntry(transcriptEntry{
			kind:  entrySystem,
			title: "queued",
			body:  "queued for next turn",
		})
	}
	return m
}

// updateInputWithKey 将按键交给 textarea 处理，并同步输入模式、布局和光标动画。
func (m appModel) updateInputWithKey(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	cmd := m.updateTokenAwareInput(msg)
	m.syncInputMode()
	m.relayout()
	m.applyCursorAnimation()
	return m, cmd
}

func (m *appModel) syncInputPasteFoldState(msg tea.Msg, beforeValue string, textChanged bool) {
	value := m.input.Value()
	if !inputPasteFoldable(value) {
		m.inputPasteFoldActive = false
		return
	}
	if m.inputPasteFoldActive {
		return
	}
	if textChanged && inputTextMutationLooksLikeMultilinePaste(msg, beforeValue, value) {
		m.inputPasteFoldActive = true
	}
}

// canMoveTextareaUp 判断 textarea 光标是否还能向上移动到上一行或上方可视行。
func canMoveTextareaUp(input textarea.Model) bool {
	lineInfo := input.LineInfo()
	return input.Line() > 0 || lineInfo.RowOffset > 0
}

// canMoveTextareaDown 判断 textarea 光标是否还能向下移动到下一行或下方可视行。
func canMoveTextareaDown(input textarea.Model) bool {
	lineInfo := input.LineInfo()
	return input.Line() < input.LineCount()-1 || lineInfo.RowOffset < lineInfo.Height-1
}

// textareaCursorAtStart 判断 textarea 光标是否位于当前输入的逻辑开头。
func textareaCursorAtStart(input textarea.Model) bool {
	if canMoveTextareaUp(input) {
		return false
	}
	lineInfo := input.LineInfo()
	return input.Line() == 0 &&
		lineInfo.RowOffset == 0 &&
		lineInfo.CharOffset == 0
}

// textareaCursorAtEnd 判断 textarea 光标是否位于当前输入的逻辑末尾。
func textareaCursorAtEnd(input textarea.Model) bool {
	if canMoveTextareaDown(input) {
		return false
	}
	lineInfo := input.LineInfo()
	cursorLine := input.Line()
	copyInput := input
	copyInput.CursorEnd()
	endInfo := copyInput.LineInfo()
	return cursorLine == copyInput.Line() &&
		lineInfo.RowOffset == endInfo.RowOffset &&
		lineInfo.ColumnOffset == endInfo.ColumnOffset
}

// handleHistoryNavigation 在输入边界处切换历史记录，并保留进入历史前的草稿。
func (m appModel) handleHistoryNavigation(direction int) (tea.Model, tea.Cmd) {
	if m.running || len(m.inputHistory) == 0 {
		return m, nil
	}

	if direction < 0 {
		m.historyDownLock = false
		if m.historyIndex == -1 {
			m.historyDraft = m.currentInputDraft()
			m.historyIndex = len(m.inputHistory) - 1
		} else if m.historyIndex > 0 {
			m.historyIndex--
		}
		m.setInputDraft(m.inputHistory[m.historyIndex])
		m.inputPasteFoldActive = false
		m.syncInputMode()
		m.relayout()
		m.applyCursorAnimation()
		return m, nil
	}

	if m.historyIndex == -1 {
		return m, nil
	}
	if m.historyIndex < len(m.inputHistory)-1 {
		m.historyIndex++
		m.setInputDraft(m.inputHistory[m.historyIndex])
		m.historyDownLock = true
	} else {
		m.historyIndex = -1
		m.setInputDraft(m.historyDraft)
		m.historyDraft = inputDraft{}
		m.historyDownLock = false
	}
	m.input.CursorEnd()
	m.inputPasteFoldActive = false
	m.syncInputMode()
	m.relayout()
	m.applyCursorAnimation()
	return m, nil
}

// rememberInputHistory 记录一条非空且不重复的用户输入历史。
func (m *appModel) rememberInputHistory(line string) {
	line = strings.TrimSpace(line)
	if line == "" {
		return
	}
	draft := inputDraft{Text: line}
	if strings.TrimSpace(m.submittedDraft.Text) == line {
		draft = trimInputDraft(m.submittedDraft)
	}
	if len(m.inputHistory) > 0 && m.inputHistory[len(m.inputHistory)-1].Text == line {
		if !inputDraftEqual(m.inputHistory[len(m.inputHistory)-1], draft) {
			m.inputHistory[len(m.inputHistory)-1] = cloneInputDraft(draft)
		}
		return
	}
	m.inputHistory = append(m.inputHistory, cloneInputDraft(draft))
}

func inputHistoryFromTranscript(entries []transcriptEntry) []inputDraft {
	history := make([]inputDraft, 0)
	for _, entry := range entries {
		if entry.kind != entryUser {
			continue
		}
		draft := trimInputDraft(inputDraft{
			Text:   entry.body,
			Tokens: cloneInputTokens(entry.inputTokens),
		})
		if draft.Text == "" {
			continue
		}
		if len(history) > 0 && history[len(history)-1].Text == draft.Text {
			if !inputDraftEqual(history[len(history)-1], draft) {
				history[len(history)-1] = cloneInputDraft(draft)
			}
			continue
		}
		history = append(history, cloneInputDraft(draft))
	}
	return history
}

// resetHistoryNavigation 清除当前历史浏览状态，回到普通编辑模式。
func (m *appModel) resetHistoryNavigation() {
	m.historyIndex = -1
	m.historyDraft = inputDraft{}
	m.historyDownLock = false
}

// submitShellCommand 提交终端命令，先写入 transcript，再异步执行 bash。
func (m appModel) submitShellCommand(command string) (tea.Model, tea.Cmd) {
	command = strings.TrimSpace(command)
	if command == "" {
		return m, nil
	}
	if !m.queryGuard.StartTerminal() {
		m.addEntry(transcriptEntry{kind: entrySystem, title: "busy", body: "terminal commands are unavailable while work is running"})
		return m, nil
	}
	m.addEntry(transcriptEntry{
		kind:  entryTool,
		title: "terminal",
		body:  "$ " + command,
	})
	m.syncRunningFlags()
	m.activeAssistant = -1
	return m, runShellCmd(m.ctx, command)
}

package bubble

import (
	"codex-agent-go/internal/loop"
	"codex-agent-go/internal/settings"
	"fmt"
	"github.com/charmbracelet/lipgloss"
	"math"
	"strconv"
	"strings"
	"time"
)

func (m appModel) contextMeterTitle() string {
	width := m.width
	if width <= 0 {
		width = contextMeterDefaultWidth
	}
	return m.contextMeterLine(maxInt(28, width-2))
}

func (m appModel) contextMeterLine(width int) string {
	stats := m.contextStats()
	limit := maxInt(1, stats.LimitTokens)
	rawUsed := maxInt(0, stats.UsedTokens)
	rawCache := clampInt(stats.CacheTokens, 0, rawUsed)
	// 进度条：easeOutBack（有轻微超出感，720ms）
	animatedUsed, animatedCache, pulse := m.animatedContextTokens(limit)
	// 标签数字：easeOutCubic（无超出，400ms），呈现快速计数跳动效果
	labelUsed, labelCache := m.animatedLabelTokens(rawUsed, rawCache, limit)
	usedLabel := formatContextUsageLabel(labelUsed, labelCache, limit, m.isGenerating)
	freeLabel := formatContextFreeLabel(labelUsed, limit)
	return renderContextMeterLine(width, usedLabel, freeLabel, animatedUsed, animatedCache, limit, m.thinkingLabel(), pulse)
}

func formatContextUsageLabel(used, cache, limit int, isGenerating bool) string {
	arrow := contextDirectionArrow(isGenerating)
	parts := []string{formatCompactTokenCount(used) + arrow}
	parts = append(parts, fmt.Sprintf("%s(%s)", formatContextPercent(used, limit), formatContextPercent(cache, limit)))
	return strings.Join(parts, " ")
}

func formatContextFreeLabel(used, limit int) string {
	free := maxInt(0, limit-used)
	return fmt.Sprintf("free(%s)", formatContextPercent(free, limit))
}

// contextDirectionArrow returns "↓" during generation, "↑" otherwise.
func contextDirectionArrow(isGenerating bool) string {
	if isGenerating {
		return "↓"
	}
	return "↑"
}

func formatContextPercent(value, total int) string {
	return fmt.Sprintf("%.0f%%", percent(clampInt(value, 0, maxInt(0, total)), total))
}

func formatCompactTokenCount(value int) string {
	value = maxInt(0, value)
	if value <= 999 {
		return strconv.Itoa(value)
	}
	scaled := float64(value) / 1000
	unit := "k"
	if value > 999000 {
		scaled = float64(value) / 1000000
		unit = "M"
	}
	text := formatThreeDigitNumber(scaled)
	if unit == "k" && strings.HasPrefix(text, "1000") {
		text = formatThreeDigitNumber(float64(value) / 1000000)
		unit = "M"
	}
	return text + unit
}

func formatThreeDigitNumber(value float64) string {
	switch {
	case value >= 100:
		return fmt.Sprintf("%.0f", value)
	case value >= 10:
		return trimTrailingDecimalZeros(fmt.Sprintf("%.1f", value))
	default:
		return trimTrailingDecimalZeros(fmt.Sprintf("%.2f", value))
	}
}

func trimTrailingDecimalZeros(text string) string {
	text = strings.TrimRight(text, "0")
	return strings.TrimRight(text, ".")
}

func (m appModel) contextStats() loop.ContextStats {
	cfg := m.currentSettings()
	limit := cfg.UI.ContextLimitTokens
	if provider, ok := m.runner.(contextStatsProvider); ok {
		return provider.ContextStats(limit, m.input.Value())
	}
	return loop.ContextStats{LimitTokens: limit}
}

func (m appModel) currentSettings() settings.Config {
	if m.settingsConfig == nil {
		return settings.DefaultConfig()
	}
	return settings.Normalize(m.settingsConfig.CurrentSettings())
}

func (m appModel) thinkingLabel() string {
	if !m.isModelWorkRunning() || m.turnStartedAt.IsZero() {
		return ""
	}
	now := m.cursorFrameAt
	if now.IsZero() {
		now = time.Now()
	}
	elapsed := now.Sub(m.turnStartedAt)
	if elapsed < 0 {
		elapsed = 0
	}
	return fmt.Sprintf("<thinking %ds>", int(elapsed.Seconds()))
}

func contextBarWidth(width int, usedLabel, freeLabel string) int {
	width = maxInt(1, width)
	barWidth := width - lipgloss.Width(usedLabel) - lipgloss.Width(freeLabel) - 2
	if barWidth >= 8 {
		return barWidth
	}
	return maxInt(contextMeterMinimumBarCells, width-lipgloss.Width(compactContextLabel(usedLabel))-lipgloss.Width(compactContextLabel(freeLabel))-2)
}

func compactContextLabel(label string) string {
	if strings.HasPrefix(label, "free(") {
		return "free"
	}
	fields := strings.Fields(label)
	if len(fields) == 0 {
		return label
	}
	if len(fields) <= 2 {
		return fields[0]
	}
	return strings.Join(fields[:2], " ")
}

func renderContextMeterLine(width int, usedLabel, freeLabel string, used, cache, limit int, overlay string, pulse float64) string {
	width = maxInt(1, width)
	barWidth := contextBarWidth(width, usedLabel, freeLabel)
	if barWidth+lipgloss.Width(usedLabel)+lipgloss.Width(freeLabel)+2 > width {
		usedLabel = compactContextLabel(usedLabel)
		freeLabel = compactContextLabel(freeLabel)
	}
	usedText := contextUsedStyle.Render(usedLabel)
	freeText := contextFreeStyle.Render(freeLabel)
	barWidth = maxInt(contextMeterMinimumBarCells, width-lipgloss.Width(usedLabel)-lipgloss.Width(freeLabel)-2)
	barOffset := lipgloss.Width(usedLabel) + 1
	overlayStart := centeredOverlayStart(width, barOffset, barWidth, overlay)
	bar := renderContextBarWithOverlayStart(used, cache, limit, barWidth, overlay, overlayStart, pulse)
	line := usedText + " " + bar + " " + freeText
	if visible := lipgloss.Width(line); visible < width {
		line += strings.Repeat(" ", width-visible)
	}
	return line
}

func renderContextBar(used, cache, limit, width int, overlay string) string {
	overlayStart := -1
	if overlayWidth := lipgloss.Width(overlay); overlayWidth > 0 && overlayWidth <= width {
		overlayStart = (width - overlayWidth) / 2
	}
	return renderContextBarWithOverlayStart(used, cache, limit, width, overlay, overlayStart, 0)
}

func renderContextBarWithOverlayStart(used, cache, limit, width int, overlay string, overlayStart int, pulse float64) string {
	limit = maxInt(1, limit)
	width = maxInt(contextMeterMinimumBarCells, width)
	usedCells := int(math.Round(float64(clampInt(used, 0, limit)) / float64(limit) * float64(width)))
	cacheCells := int(math.Round(float64(clampInt(cache, 0, used)) / float64(limit) * float64(width)))
	if cacheCells > usedCells {
		cacheCells = usedCells
	}
	cells := make([]string, width)
	for i := 0; i < width; i++ {
		switch {
		case i < cacheCells:
			cells[i] = contextCacheStyle.Render("▰")
		case i < usedCells:
			cells[i] = contextUsedPulseStyle(pulse, i, usedCells).Render("▰")
		default:
			cells[i] = contextFreeStyle.Render("▱")
		}
	}
	overlayWidth := lipgloss.Width(overlay)
	if overlayWidth > 0 && overlayStart >= 0 && overlayStart+overlayWidth <= width {
		cells[overlayStart] = contextThinkingStyle.Render(overlay)
		for i := 1; i < overlayWidth; i++ {
			cells[overlayStart+i] = ""
		}
	}
	return strings.Join(cells, "")
}

func (m *appModel) updateContextMeterAnimation() {
	now := m.animationNow()
	stats := m.contextStats()
	limit := maxInt(1, stats.LimitTokens)
	used := clampInt(maxInt(0, stats.UsedTokens), 0, limit)
	cache := clampInt(stats.CacheTokens, 0, used)
	if !m.contextMeter.initialized {
		m.contextMeter = contextMeterAnimation{
			initialized: true,
			startedAt:   now,
			fromUsed:    float64(used),
			fromCache:   float64(cache),
			targetUsed:  used,
			targetCache: cache,
		}
		return
	}
	if m.contextMeter.targetUsed == used && m.contextMeter.targetCache == cache {
		return
	}
	currentUsed, currentCache, _ := m.animatedContextTokens(limit)
	m.contextMeter.startedAt = now
	m.contextMeter.fromUsed = float64(currentUsed)
	m.contextMeter.fromCache = float64(currentCache)
	m.contextMeter.targetUsed = used
	m.contextMeter.targetCache = cache
}

func (m appModel) animatedContextTokens(limit int) (int, int, float64) {
	if !m.contextMeter.initialized {
		return m.contextMeter.targetUsed, m.contextMeter.targetCache, 0
	}
	now := m.animationNow()
	elapsed := now.Sub(m.contextMeter.startedAt)
	if elapsed < 0 {
		elapsed = 0
	}
	const duration = 720 * time.Millisecond
	progress := clamp01(float64(elapsed) / float64(duration))
	eased := easeOutBack(progress)
	animatedUsed := int(math.Round(lerp(m.contextMeter.fromUsed, float64(m.contextMeter.targetUsed), eased)))
	animatedCache := int(math.Round(lerp(m.contextMeter.fromCache, float64(m.contextMeter.targetCache), eased)))
	animatedUsed = clampInt(animatedUsed, 0, limit)
	animatedCache = clampInt(animatedCache, 0, animatedUsed)
	return animatedUsed, animatedCache, contextPulse(progress)
}

// animatedLabelTokens 用 easeOutCubic + 400ms 为数字标签计算动画值。
// 动画未初始化时回退到 rawUsed/rawCache（立即显示真实值）。
func (m appModel) animatedLabelTokens(rawUsed, rawCache, limit int) (used, cache int) {
	if !m.contextMeter.initialized {
		return clampInt(rawUsed, 0, limit), clampInt(rawCache, 0, clampInt(rawUsed, 0, limit))
	}
	now := m.animationNow()
	elapsed := now.Sub(m.contextMeter.startedAt)
	if elapsed < 0 {
		elapsed = 0
	}
	const labelDuration = 400 * time.Millisecond
	progress := clamp01(float64(elapsed) / float64(labelDuration))
	eased := easeOutCubic(progress)
	animUsed := int(math.Round(lerp(m.contextMeter.fromUsed, float64(m.contextMeter.targetUsed), eased)))
	animCache := int(math.Round(lerp(m.contextMeter.fromCache, float64(m.contextMeter.targetCache), eased)))
	animUsed = clampInt(animUsed, 0, limit)
	animCache = clampInt(animCache, 0, animUsed)
	return animUsed, animCache
}

func contextPulse(progress float64) float64 {
	if progress <= 0 || progress >= 1 {
		return 0
	}
	return math.Sin(progress * math.Pi)
}

func contextUsedPulseStyle(pulse float64, index, usedCells int) lipgloss.Style {
	if pulse <= 0 || usedCells <= 0 || index < usedCells-2 {
		return contextUsedStyle
	}
	return contextUsedStyle.Copy().Foreground(colorManager.LipglossColor(colorMarkdownHeading)).Bold(true)
}

func lerp(from, to, t float64) float64 {
	return from + (to-from)*t
}

func easeOutBack(t float64) float64 {
	t = clamp01(t)
	const c1 = 1.70158
	const c3 = c1 + 1
	x := t - 1
	return 1 + c3*x*x*x + c1*x*x
}

func centeredOverlayStart(lineWidth, barOffset, barWidth int, overlay string) int {
	overlayWidth := lipgloss.Width(overlay)
	if overlayWidth == 0 || overlayWidth > barWidth {
		return -1
	}
	start := (lineWidth-overlayWidth)/2 - barOffset
	if start < 0 || start+overlayWidth > barWidth {
		return (barWidth - overlayWidth) / 2
	}
	return start
}

func percent(value, total int) float64 {
	if total <= 0 {
		return 0
	}
	return float64(value) / float64(total) * 100
}

func clampInt(value, minValue, maxValue int) int {
	if value < minValue {
		return minValue
	}
	if value > maxValue {
		return maxValue
	}
	return value
}

// renderContextCardContent 为右侧 Context 卡片渲染多行内容。
// 输出 token 数、进度条，以及压缩后的 cache/free/turns 状态。
func (m appModel) renderContextCardContent(innerWidth int) string {
	stats := m.contextStats()
	limit := maxInt(1, stats.LimitTokens)
	rawUsed := maxInt(0, stats.UsedTokens)
	rawCache := clampInt(stats.CacheTokens, 0, rawUsed)
	labelUsed, labelCache := m.animatedLabelTokens(rawUsed, rawCache, limit)

	// Line 1: cache% left (hit rate = cache / used), token centre-left, free right.
	cacheLabel := "cache " + formatContextPercent(labelCache, labelUsed)
	rawToken := formatCompactTokenCount(labelUsed) + contextDirectionArrow(m.isGenerating)
	rawFree := formatContextFreeLabel(labelUsed, limit)
	cacheVW := len([]rune(cacheLabel))
	tokenVW := len([]rune(rawToken))
	freeVW := len([]rune(rawFree))
	gap := maxInt(1, innerWidth-cacheVW-1-tokenVW-freeVW)
	topLine := contextCacheStyle.Render(cacheLabel) + " " + contextUsedStyle.Render(rawToken) + strings.Repeat(" ", gap) + contextFreeStyle.Render(rawFree)

	// Line 2: progress bar
	animatedUsed, animatedCache, _ := m.animatedContextTokens(limit)
	bar := renderContextBar(animatedUsed, animatedCache, limit, innerWidth, "")

	lines := []string{topLine, bar}
	if supplementLine := m.contextWorkStatusLine(innerWidth); supplementLine != "" {
		lines = append(lines, supplementLine)
	}

	return strings.Join(lines, "\n")
}

func centeredContextStatusLine(width int, parts ...string) string {
	return compactContextStatusLine(width, nonEmptyStrings(parts...))
}

func compactContextStatusLine(width int, options ...[]string) string {
	if width <= 0 {
		return ""
	}
	for _, parts := range options {
		visible := strings.Join(nonEmptyStrings(parts...), " · ")
		if lipgloss.Width(visible) <= width {
			return centeredContextStatusText(width, visible)
		}
	}
	if len(options) == 0 {
		return centeredContextStatusText(width, "")
	}
	fallback := strings.Join(nonEmptyStrings(options[len(options)-1]...), " ")
	return centeredContextStatusText(width, trimVisibleWidth(fallback, width))
}

func centeredContextStatusText(width int, visible string) string {
	return lipgloss.NewStyle().
		Width(width).
		Align(lipgloss.Center).
		Foreground(colorManager.LipglossColor(colorContextFree)).
		Render(visible)
}

func trimVisibleWidth(text string, width int) string {
	if width <= 0 || lipgloss.Width(text) <= width {
		return text
	}
	runes := []rune(text)
	for lipgloss.Width(string(runes)) > width && len(runes) > 0 {
		runes = runes[:len(runes)-1]
	}
	return string(runes)
}

func (m appModel) contextPercentStatusLine(width int, cachePct, freePct string) string {
	turns := m.turnsCount()
	return compactContextStatusLine(
		width,
		[]string{"cache " + cachePct, "free " + freePct, fmt.Sprintf("turns %d", turns)},
		[]string{"cache" + cachePct, "free" + freePct, fmt.Sprintf("turns%d", turns)},
		[]string{"c" + cachePct, "f" + freePct, fmt.Sprintf("t%d", turns)},
	)
}

func (m appModel) contextWorkStatusLine(width int) string {
	var full []string
	var compact []string
	var tiny []string
	if supplements := m.pendingSupplementCount(); supplements > 0 {
		full = append(full, fmt.Sprintf("supplements %d", supplements))
		compact = append(compact, fmt.Sprintf("supp %d", supplements))
		tiny = append(tiny, fmt.Sprintf("s%d", supplements))
	}
	if queued := m.chatQueue.Len(); queued > 0 {
		full = append(full, fmt.Sprintf("queued %d", queued))
		compact = append(compact, fmt.Sprintf("queue %d", queued))
		tiny = append(tiny, fmt.Sprintf("q%d", queued))
	}
	if len(full) == 0 {
		return ""
	}
	return compactContextStatusLine(width, full, compact, tiny)
}

func (m appModel) pendingSupplementCount() int {
	provider, ok := m.runner.(SupplementStatsProvider)
	if !ok {
		return 0
	}
	return provider.PendingSupplementCount()
}
